"""Builds assets/lifefx-light.css: the light-theme twin of assets/lifefx.css (Life pages follow the site theme; light is the default).
Every colour in lifefx.css that only works on a dark ground gets a light counterpart under :root:not([data-theme=dark]). Run by make-pages.py."""
import re, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
src = (ROOT / 'assets' / 'lifefx.css').read_text()
KEEP = ('.pht b', '.pht small', '.fb', '.lact button.go', '.wcc', '.lrv .cap.hc', '.lrv .cap.f', '.lrv .cap.fcap', '.lrv .cap{', '.lbtn', '.yb i', '.lgbar', '.mpc.all', '.lstrip .wk', '.lend', '.phb .s', '.fc .pht')
TEXT = {'#fff': '#0b1220', '#ffffff': '#0b1220', '#eaf0ff': '#0b1220', '#dfe6ff': '#3a4252', '#cbd3ee': '#3a4252', '#d6ddf5': '#3a4252', '#e4eaff': '#3a4252', '#c9cfe6': '#3a4252', '#e7dcff': '#3a4252', '#dfe6ffaa': '#5b6478', '#e9ecf8': '#3a4252',
        '#ffd1ea': '#b0005f', '#ff7ac2': '#c4006b', '#9fdcff': '#00639e', '#9fe6ff': '#00639e', '#bfefff': '#00639e', '#cdeeff': '#00639e', '#ffe7a6': '#7a5200', '#ffe08a': '#7a5200', '#ffc2e2': '#b0005f', '#ffb3d6': '#b0005f', '#ffb3c8': '#c0003a', '#9ff5c7': '#0b7a43', '#93a0c4': '#5b6478', '#8ea0c8': '#5b6478',
        '#ffffff55': '#0b122066', '#ffffff70': '#0b122080', '#ffffffaa': '#0b1220aa', '#ffffff66': '#0b122080', '#04121c': '#04121c', '#29c6ff': '#0088c7', '#2fe08a': '#0f9d57', '#ffc93c': '#9a6a00', '#ff2d95': '#d6006f'}
def bg(v):
    v = v.lower()
    if re.fullmatch(r'#(05070f|0b1230|020308|0a0f2a)[0-9a-f]{0,2}', v): return '#ffffffd9'
    m = re.fullmatch(r'#ffffff([0-9a-f]{2})', v)
    if m: a = int(m.group(1), 16); return '#0b1220%02x' % max(8, min(40, a))
    if v in ('#141b38',): return '#e6e9f4'
    if v.startswith('#2b3560'): return '#c3c9e0'
    if v.startswith('#1d2a4a') or v.startswith('#162040') or v.startswith('#121a30'): return '#e9ecf6'
    return None
def twin(prop, val):
    p = prop.strip().lower()
    if p == 'color':
        v = val.strip().lower().replace('!important', '').strip()
        if v in TEXT and TEXT[v] != v: return f'color:{TEXT[v]}' + ('!important' if 'important' in val else '')
    if p in ('background', 'background-color'):
        v = val.strip()
        if re.fullmatch(r'#[0-9a-fA-F]{3,8}', v): n = bg(v); return f'{p}:{n}' if n else None
        if 'linear-gradient(160deg,#ffffff' in v or 'linear-gradient(135deg,#ffffff' in v: return f'{p}:linear-gradient(160deg,#ffffffeb,#ffffffb3)'
    if p.startswith('border') and re.search(r'#ffffff[0-9a-f]{2}', val, re.I): return p + ':' + re.sub(r'#ffffff([0-9a-f]{2})', '#0b12201f', val, flags=re.I)
    if p == '-webkit-text-fill-color': return None
    return None
out = []
for m in re.finditer(r'(@media[^{]+)\{((?:[^{}]*\{[^}]*\})*)\s*\}|([^{}@]+)\{([^}]*)\}', src):
    if m.group(1):
        if 'print' in m.group(1) or 'reduced' in m.group(1): continue
        inner = m.group(2); med = m.group(1).strip(); rules = []
        for r in re.finditer(r'([^{}]+)\{([^}]*)\}', inner): rules.append((r.group(1), r.group(2)))
    else: med = None; rules = [(m.group(3), m.group(4))]
    for sel, body in rules:
        sel = sel.strip()
        if sel.startswith('/*'): sel = re.sub(r'/\*.*?\*/', '', sel, flags=re.S).strip()
        if not sel or any(k in sel + '{' for k in KEEP): continue
        decls = [t for t in (twin(*d.split(':', 1)) for d in re.split(r';(?![^()]*\))', body) if ':' in d) if t]
        if not decls: continue
        sels = ','.join(':root:not([data-theme=dark]) ' + s.strip() for s in sel.split(','))
        rule = sels + '{' + ';'.join(decls) + '}'
        out.append(med + '{' + rule + '}' if med else rule)
HEAD = """/* GENERATED by dev/make-lifelight.py from lifefx.css. Do not edit by hand. Life pages follow the site theme: this is the light (default) look. */
:root:not([data-theme=dark]) .lx{--lb:#f4f6fc;--li:#2a3142;--lm:#5b6478;--lk:#e6e9f4;--lw:#c3c9e0;--lt:#0b1220;--lcell:#0b122012;color:var(--li);background:radial-gradient(1100px 620px at 85% -10%,#7a5cff2e 0,transparent 60%),radial-gradient(900px 600px at 0 0,#009fe326 0,transparent 55%),radial-gradient(700px 500px at 50% 110%,#e5007d1f 0,transparent 60%),var(--lb)}
:root:not([data-theme=dark]) .lx h1,:root:not([data-theme=dark]) .lx h2,:root:not([data-theme=dark]) .lx h3,:root:not([data-theme=dark]) .lx h4{color:#0b1220!important}
:root:not([data-theme=dark]) .lx .crumbp b{color:#0b1220!important}:root:not([data-theme=dark]) .lx a{color:#00639e!important}
:root:not([data-theme=dark]) .lglass{box-shadow:0 24px 50px -34px #281e7866;border-color:#0b12201a}
:root:not([data-theme=dark]) .lhero{background:linear-gradient(135deg,#ff2d951f,#6d4cff1c 50%,#29c6ff1a);border-color:#0b12201a;box-shadow:0 24px 50px -34px #281e7866}
:root:not([data-theme=dark]) .lhero:after{background:radial-gradient(#ff2d9555,transparent 70%)}
:root:not([data-theme=dark]) .lxctl select,:root:not([data-theme=dark]) .lxctl input[type=number],:root:not([data-theme=dark]) .lxctl input[type=date],:root:not([data-theme=dark]) .lxctl input[type=datetime-local],:root:not([data-theme=dark]) .lxctl input[type=text],:root:not([data-theme=dark]) .lxctl input[type=time],:root:not([data-theme=dark]) .lhnext select,:root:not([data-theme=dark]) .cpick select,:root:not([data-theme=dark]) .trbar select,:root:not([data-theme=dark]) .trform textarea{background:#fff;color:#0b1220;border-color:#0b122033;color-scheme:light}
:root:not([data-theme=dark]) .lseg button[aria-pressed=true]{background:#0b1220;color:#fff;border-color:#0b1220}
:root:not([data-theme=dark]) .lx .tbtn:not(.go),:root:not([data-theme=dark]) .lact button:not(.go),:root:not([data-theme=dark]) .lxctl .lbtnrow button,:root:not([data-theme=dark]) .lzx,:root:not([data-theme=dark]) .trline .ta button{background:#fff;color:#0b1220;border-color:#0b122026}
:root:not([data-theme=dark]) .lx .tbtn.go,:root:not([data-theme=dark]) .lx .lact button.go{background:linear-gradient(135deg,#e5007d,#6d4cff);color:#fff;border:0}:root:not([data-theme=dark]) .lx .lact button.go:disabled{opacity:.4}
:root:not([data-theme=dark]) .lact a.lbtn,:root:not([data-theme=dark]) .lhnext .lbtn{background:#fff;border-color:#0088c766;color:#00639e!important}
:root:not([data-theme=dark]) .ltk:before,:root:not([data-theme=dark]) .ltk:after{background:var(--lb)}
:root:not([data-theme=dark]) .ltk .r b{background:linear-gradient(#0b1220,#0088c7);-webkit-background-clip:text;background-clip:text}
:root:not([data-theme=dark]) .lmo{background:#fff;border-color:#0088c733;box-shadow:0 10px 24px -18px #281e7855}
:root:not([data-theme=dark]) .lmg span.h{background:#ff2d95;color:#fff;box-shadow:0 0 9px #ff2d9588}:root:not([data-theme=dark]) .lmg span.l{background:#2fe08a;color:#04160c;box-shadow:0 0 9px #2fe08a88}:root:not([data-theme=dark]) .lmg span.w{background:#c3c9e0}:root:not([data-theme=dark]) .lmg .l{color:#04160c}:root:not([data-theme=dark]) .lmg .b{outline-color:#0088c7aa}
:root:not([data-theme=dark]) .lrv .now{background:#0b1220;box-shadow:none}:root:not([data-theme=dark]) .lrv .now:after{color:#0b1220}
:root:not([data-theme=dark]) .lhclock .tm{color:#0b1220;text-shadow:0 0 30px #29c6ff44}:root:not([data-theme=dark]) .wcbig{color:#0b1220;text-shadow:0 0 30px #29c6ff44}
:root:not([data-theme=dark]) .lhp{color:#0b1220!important}:root:not([data-theme=dark]) .lhp .ic{background:#fff}:root:not([data-theme=dark]) .lhp b{color:#0b1220}
:root:not([data-theme=dark]) .lroad li:before{background:#fff}:root:not([data-theme=dark]) .lsel{background:#0b1220;box-shadow:none}
:root:not([data-theme=dark]) .lstrip .nt{background:#e6e9f4;color:#0b122066}:root:not([data-theme=dark]) .lstrip .dy{background:#29c6ff40;color:#00507f}
:root:not([data-theme=dark]) .fstrip{background:#29c6ff1f}:root:not([data-theme=dark]) .fn{background:#c3c9e0}:root:not([data-theme=dark]) .fh em{color:#0b1220}:root:not([data-theme=dark]) .fh{background:#0b122040}
:root:not([data-theme=dark]) .mpc{background:rgba(0,136,199,calc(var(--f) * .55 + .06))}
:root:not([data-theme=dark]) .ltrack{background:#0b122012}:root:not([data-theme=dark]) .lnow{background:#0b1220;box-shadow:none}:root:not([data-theme=dark]) .lnow em{color:#0b1220}:root:not([data-theme=dark]) .lend{border-color:#fff}
:root:not([data-theme=dark]) .phc{background:linear-gradient(160deg,#ffffffeb,#ffffffb3)}:root:not([data-theme=dark]) .phc.past .pht{background:#c3c9e0}
"""
new = HEAD + '\n'.join(out) + '\n'
p = ROOT / 'assets' / 'lifefx-light.css'
if not p.exists() or p.read_text() != new: p.write_text(new)
if __name__ == '__main__': print('lifefx-light.css', len(new), 'bytes,', len(out), 'rules')
